// === Tab: mySketch ===
const vs = `
attribute vec3 aPosition;
attribute vec4 aMaterialColor;
attribute vec3 aNoiseArray;

uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;

varying vec4 vColor;

uniform float uMixcoef;

void main(void) {
   vec3 position = aPosition + aNoiseArray * uMixcoef;
   gl_Position = uProjectionMatrix * uModelViewMatrix * vec4(position, 1.0);
   vColor = aMaterialColor;
}
`;

const fs = `
precision highp float;

varying vec4 vColor;

void main(void) {
   gl_FragColor = vColor;
}
`;

const w = 1112;
const fps = 24;
const P = 64;
const l = w/4;
let theShader;

function setup() {
   _gl = createCanvas(w, w*.75, WEBGL);
   frameRate(fps);

   colorMode(HSB);
   noStroke();

   theShader = createShader(vs, fs);
   _gl.retainedMode.buffers.fill.push(new p5.RenderBuffer(3, "noiseArray", "noiseBuffer", "aNoiseArray", _gl));
}

function draw() {
   shader(theShader);
   theShader.setUniform('uMixcoef', sin(frameCount/64));

   background(20);
   push();
   rotateX(frameCount/27);
   rotateY(-frameCount/33);
   translate(0, 0, 0);
   noisy_sphere(l, P, P);
   pop();

   resetShader();
}

function noisy_sphere(size, detailX, detailY) {
   const gId = `noisy_sphere|${size}|${detailX}|${detailY}`;

   if (!this._renderer.geometryInHash(gId)) {
      let geom = new p5.Geometry(detailX, detailY);
      geom.noiseArray = [];

       for (var i = 0; i <= detailY; i++) {
         var v = i / detailY;
         var phi = Math.PI * v - Math.PI / 2;
         var cosPhi = Math.cos(phi);
         var sinPhi = Math.sin(phi);

         for (var j = 0; j <= detailX; j++) {
           var u = j / detailX;
           var theta = 2 * Math.PI * u;
           var cosTheta = Math.cos(theta);
           var sinTheta = Math.sin(theta);
           var p = new p5.Vector(
             cosPhi * sinTheta,
             sinPhi,
             cosPhi * cosTheta
           );
           geom.vertices.push(p);
           geom.vertexNormals.push(p);
           geom.uvs.push(u, v);

           geom.vertexColors.push(1,
            .4, sin((i-detailY/2)/10)*0.3+0.3,
            sin((i-detailY/2)/10)*0.4+0.6);
         }
       }

       let dd = 1.1;
       let weight = 0.05;
       let p0 = [];
       let k=random();
       for (var i = 0; i <= detailY; i++) {
         for (var j = 0; j <= detailX; j++) {
            var p = [
               dd*(noise(i*weight, j*weight, k+0) - 0.5),
               dd*(noise(i*weight, j*weight, k+1) - 0.5),
               dd*(noise(i*weight, j*weight, k+2) - 0.5)
            ];

           if(j==0){p0=p;}
           if(j==detailX || i==0 || i==detailY){p=p0;}
           geom.noiseArray.push(...p);
         }
       }
     geom.computeFaces();
     geom._makeTriangleEdges()._edgesToVertices();
     this._renderer.createBuffers(gId, geom);
   }
   this._renderer.drawBuffersScaled(gId, size, size, size);
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  // prevents mouse press from registering twice
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  }
}

